/** Names of the icons in the set. */
export const ICON_NAMES = Object.keys(P);

/** SVG markup for one icon. size in px; decorative (aria-hidden) unless a label is given. */
export function iconSvg(name, { size = 22, className = "", label = "" } = {}) {
  const d = P[name];
  if (!d) throw new Error(`Unknown Nimbo icon: ${name}`);
  const a11y = label ? ` role="img" aria-label="${label}"` : ` aria-hidden="true" focusable="false"`;
  return `<svg${className ? ` class="${className}"` : ""} viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"${a11y}><path fill-rule="evenodd" d="${d}"/></svg>`;
}
